namespace sv_54d655ec4a87443eb2a4318c84d3b49b.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

public sealed record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public sealed record StatusUpdate(
    DateTimeOffset Timestamp,
    string Status,
    string Location);

using sv_54d655ec4a87443eb2a4318c84d3b49b.Client.Services;

namespace sv_54d655ec4a87443eb2a4318c84d3b49b.Services;

public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new ShipmentDetails(
            "TRK-001",
            "In Transit",
            "Chicago, IL",
            new DateTimeOffset(2026, 7, 2, 17, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate(new DateTimeOffset(2026, 6, 23, 8, 0, 0, TimeSpan.Zero), "Picked Up", "New York, NY"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 24, 14, 30, 0, TimeSpan.Zero), "In Transit", "Philadelphia, PA"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 25, 19, 15, 0, TimeSpan.Zero), "In Transit", "Chicago, IL"),
            ]),

        ["TRK-002"] = new ShipmentDetails(
            "TRK-002",
            "Delivered",
            "San Francisco, CA",
            new DateTimeOffset(2026, 6, 25, 12, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate(new DateTimeOffset(2026, 6, 20, 10, 0, 0, TimeSpan.Zero), "Picked Up", "Seattle, WA"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 21, 16, 0, 0, TimeSpan.Zero), "In Transit", "Portland, OR"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 23, 9, 0, 0, TimeSpan.Zero), "Out for Delivery", "San Francisco, CA"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 23, 14, 22, 0, TimeSpan.Zero), "Delivered", "San Francisco, CA"),
            ]),

        ["TRK-003"] = new ShipmentDetails(
            "TRK-003",
            "Processing",
            "Dallas, TX",
            new DateTimeOffset(2026, 7, 5, 18, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate(new DateTimeOffset(2026, 6, 26, 7, 0, 0, TimeSpan.Zero), "Label Created", "Dallas, TX"),
            ]),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);
        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using System.Net.Http.Json;

namespace sv_54d655ec4a87443eb2a4318c84d3b49b.Client.Services;

public sealed class ClientShipmentService(HttpClient http) : IShipmentService
{
    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct);
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_54d655ec4a87443eb2a4318c84d3b49b.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<Shipment> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
        Loading shipment <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm mt-2" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning" role="alert">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <h1>Shipment @_shipment.TrackingNumber</h1>

    <dl class="row">
        <dt class="col-sm-3">Status</dt>
        <dd class="col-sm-9">@_shipment.Status</dd>

        <dt class="col-sm-3">Location</dt>
        <dd class="col-sm-9">@_shipment.Location</dd>

        <dt class="col-sm-3">Estimated Delivery</dt>
        <dd class="col-sm-9">@_shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h2>Tracking History</h2>
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Time</th>
                <th>Status</th>
                <th>Location</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var update in _shipment.Updates)
            {
                <tr>
                    <td>@update.Timestamp.ToString("g")</td>
                    <td>@update.Status</td>
                    <td>@update.Location</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private CancellationTokenSource? _cts;
    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private string _lastTrackingNumber = string.Empty;

    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(_lastTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase))
            return;

        _lastTrackingNumber = TrackingNumber;
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request.
        await CancelPendingAsync();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loading = true;
        _errorMessage = null;
        _shipment = null;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation away or disposal — silently stop.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading the shipment. Please try again.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private async Task RetryAsync() => await LoadShipmentAsync();

    private async ValueTask CancelPendingAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

